import org.apache.commons.codec.StringDecoder;
import org.apache.commons.codec.StringEncoder;
import org.apache.commons.codec.binary.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class QuotedPrintableCodec_encodeQuotedPrintable_TriageGen1Test {

    private static final BitSet PRINTABLE_CHARS = new BitSet();
    static {
        // Mimic standard printable characters for testing purposes
        for (int i = 33; i <= 126; i++) {
            PRINTABLE_CHARS.set(i);
        }
        PRINTABLE_CHARS.set(32); // Space
    }



    @Test
    public void testEncodeQuotedPrintable_NullPrintable() {
        // When printable is null, it should use the default (PRINTABLE_CHARS)
        // We test this by passing a byte that is definitely not in the default set
        byte[] input = new byte[]{(byte) 0x01}; 
        byte[] result = QuotedPrintableCodec.encodeQuotedPrintable(null, input);

        assertNotNull(result);
        // Since 0x01 is not printable, it should be encoded as =01
        // Note: The exact encoding depends on the internal encodeQuotedPrintable(int, OutputStream)
        // but we verify it's not the raw byte.
        assertFalse(result.length == 1 && result[0] == 0x01);
    }










}

